type PreloadableComponent<P, M = unknown> = ComponentType<P> & {
    /** Start (or join) the chunk load. A rejected load is retried by the next call. */
    preload: () => Promise<M>;
    /** True once the chunk has resolved, so a render now cannot suspend. */
    isLoaded: () => boolean;
};
